mapper.update:
UPDATE med_slot slot
INNER JOIN med_schedule schedule
    ON schedule.id = slot.schedule_id
SET slot.remaining_capacity = slot.remaining_capacity - 1
WHERE slot.id = #{slotId}
  AND slot.remaining_capacity > 0
  AND slot.status = #{openStatus}
  AND slot.booking_deadline > #{now,jdbcType=TIMESTAMP}
  AND schedule.status = #{publishedStatus}
